pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/introspection/IERC165.sol";

interface IConfidentialInitializationStrategy is IERC165 {
    enum LaunchStatus {
        NONE,
        MIGRATING,
        COMPLETED
    }

    struct LaunchRecord {
        bytes32 authorizationHash;
        bytes32 poolKey;
        address creator;
        address pool;
        uint64 migrationDeadline;
        LaunchStatus status;
    }

    event MigratorConfigured(address indexed migrator, bytes32 runtimeCodehash);
    event FactoryRegistrationBound(bytes32 indexed registration);
    event LaunchPrepared(
        bytes32 indexed launchId,
        bytes32 indexed poolKey,
        address indexed pool,
        address creator,
        uint64 migrationDeadline,
        bytes32 authorizationHash
    );
    event LaunchInitializationAuthorized(
        bytes32 indexed launchId,
        address indexed pool,
        address indexed creator,
        bytes32 authorizationHash
    );

    function STRATEGY_VERSION() external view returns (uint256);
    function PROTOCOL_VERSION() external view returns (uint256);
    function PRIVACY_MODE() external view returns (uint8);
    function factory() external view returns (address);
    function strategyRegistry() external view returns (address);
    function migrator() external view returns (address);
    function migratorRuntimeCodehash() external view returns (bytes32);
    function configurationFinalized() external view returns (bool);
    function factoryRegistration() external view returns (bytes32);

    function bindFactoryRegistration(bytes32 registration) external;
    function prepareLaunch(
        bytes32 launchId,
        address creator,
        address tokenA,
        address tokenB,
        uint8 decimalsA,
        uint8 decimalsB,
        uint256 feeBps,
        uint64 migrationDeadline,
        bytes32 authorizationHash
    ) external returns (address pool, bytes32 poolKey);
    function authorizeInitialization(
        bytes32 launchId,
        address migratorCaller,
        address pool,
        address creator,
        bytes32 authorizationHash
    ) external returns (bytes32 poolKey);
    function getLaunch(bytes32 launchId) external view returns (LaunchRecord memory);
    function activeLaunchForPoolKey(bytes32 poolKey) external view returns (bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@coti-io/coti-contracts/contracts/utils/mpc/MpcCore.sol";

interface IConfidentialLaunchpadMigrator {
    struct MigrationRequest {
        bytes32 launchId;
        address tokenA;
        address tokenB;
        uint8 decimalsA;
        uint8 decimalsB;
        uint256 feeBps;
        itUint256 amount0;
        itUint256 amount1;
        itUint256 minShares;
        itUint256 minPriceX18;
        itUint256 maxPriceX18;
        uint64 deadline;
        bytes authorization;
    }

    event LaunchpadMigration(
        bytes32 indexed launchId,
        address indexed creator,
        address indexed pool,
        address initializationStrategy,
        bytes32 authorizationHash
    );
    event LaunchpadLockDisposition(
        address indexed creator,
        address indexed pool,
        uint8 disposition,
        bytes32 lockId,
        uint64 unlockTime
    );

    function PROTOCOL_VERSION() external view returns (uint256);
    function factory() external view returns (address);
    function initializationStrategy() external view returns (address);

    function migrate(MigrationRequest calldata request)
        external
        returns (address pool, ctUint256 memory mintedShares);

    function migrateWithDisposition(
        MigrationRequest calldata request,
        uint8 disposition,
        uint64 unlockTime
    ) external returns (address pool, ctUint256 memory mintedShares, bytes32 lockId);

}

